from inspect import remote,W
import json
sql="""SELECT jsonb_build_object('campaign',(SELECT jsonb_build_object('id',c.id,'status',c.status,'percent',c.beneficio_percentual,'annual_code',p.codigo,'annual_type',p.tipo,'annual_year',p.ano,'version',c.version) FROM estudo.campanhas c JOIN estudo.produtos p ON p.id=c.beneficio_produto_id WHERE c.codigo='abraceo-primeiro-acesso'),
'vouchers',(SELECT jsonb_agg(jsonb_build_object('id',v.id,'status',v.status,'identity_hash',md5(jsonb_build_array(v.id,v.campanha_id,v.codigo_hash,v.email_destinatario,v.expira_em)::text)) ORDER BY v.id) FROM estudo.vouchers v JOIN estudo.campanhas c ON c.id=v.campanha_id WHERE c.codigo='abraceo-primeiro-acesso'),
'grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'status',a.status,'benefit',b.id,'percent',b.percentual,'benefit_status',b.status,'annual_code',p.codigo)),'[]') FROM estudo.acessos a JOIN estudo.vouchers v ON v.id=a.voucher_id JOIN estudo.campanhas c ON c.id=v.campanha_id LEFT JOIN estudo.beneficios b ON b.acesso_id=a.id LEFT JOIN estudo.produtos p ON p.id=b.produto_id WHERE c.codigo='abraceo-primeiro-acesso'),
'campaign_audits',(SELECT count(*) FROM estudo.auditoria_comercial WHERE acao='CAMPAIGN_ANNUAL_BENEFIT' AND entidade_id=(SELECT id FROM estudo.campanhas WHERE codigo='abraceo-primeiro-acesso')),
'gap',(SELECT count(*) FROM estudo.acessos a JOIN estudo.vouchers v ON v.id=a.voucher_id JOIN estudo.campanhas c ON c.id=v.campanha_id WHERE c.codigo='abraceo-primeiro-acesso' AND a.status='ACTIVE' AND v.status='REDEEMED' AND NOT EXISTS(SELECT 1 FROM estudo.beneficios b WHERE b.acesso_id=a.id)),
'annual_read_grants',(SELECT count(*) FROM estudo.acessos a JOIN estudo.produtos p ON p.id=a.produto_id WHERE p.codigo='anual-2026' AND a.status='ACTIVE'))::text AS payload"""
r=remote("print(json.dumps(bridge(ROOT,raw_query(payload['sql'])+'report=deserializeJSON(q.payload[1]);')))",{'sql':sql})
before=json.loads((W/'benefit-before.json').read_text());c=r['campaign'];assert c['percent']==50 and c['annual_code']=='anual-2026' and c['annual_type']=='ANUAL' and c['annual_year']==2026 and c['version']==before['campaign']['version']+1 and c['status']==before['campaign']['status']
old={i['id']:i['identity_hash']for i in before['vouchers']};new={i['id']:i['identity_hash']for i in r['vouchers']};assert all(new.get(i)==h for i,h in old.items()),'Voucher identity/expiry changed';assert r['gap']==0 and r['campaign_audits']>=1
assert r['annual_read_grants']==0,'Unexpected annual reading access'
(W/'benefit-after.json').write_text(json.dumps(r,ensure_ascii=False,indent=2));print({'campaign_percent':50,'annual':'anual-2026','vouchers_preserved':len(old),'ready_vouchers':sum(i['status']=='READY'for i in r['vouchers']),'prior_grants':len(before['grants']),'grants_now':len(r['grants']),'missing_benefits':0,'annual_read_grants':0,'audited':True})
